/**
 * Do not edit this file. Edit the config files found in the config/ dir instead.
 * This file has to live next to the docroot so WordPress can find it: WP only
 * looks in its own directory or one directory up for wp-config.php.
 */

/**
 * Docroot, passé explicitement plutôt que déduit dans application.php : ce
 * fichier-ci est le seul dont l'emplacement est garanti par WordPress. Une
 * déduction depuis application.php casserait dès que config/ serait atteint par
 * un lien symbolique, PHP résolvant __DIR__ vers le chemin réel.
 */
$optelya_webroot_dir = __DIR__;

/**
 * WPCACHEHOME est défini dans config/application.php. Ce nom doit rester écrit
 * ici : WP Super Cache le cherche dans ce fichier et, s'il ne le trouve pas, y
 * ajoute sa propre définition, qui fait planter la configuration (constante
 * définie deux fois). Voir readme/cache.md.
 */

require_once __DIR__ . '/vendor/autoload.php';
require_once dirname(__DIR__) . '/config/application.php';
require_once ABSPATH . 'wp-settings.php';
